using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// --- Build chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Register tools ---
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(notebook.TakeNote),
    AIFunctionFactory.Create(notebook.ReadNotes),
};

var chatOptions = new ChatOptions { Tools = tools };

// --- System prompt ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly
        by searching the web and compiling your findings into clear notes.

        Workflow:
        1. Break the topic into key questions.
        2. Use the SearchWeb tool to find information (try several varied queries).
        3. Use the TakeNote tool to record important facts, data, and sources.
        4. Use ReadNotes to review what you've gathered so far.
        5. After sufficient research (at least 3 searches), write a final
           summary that synthesizes all your notes into a well-structured report.

        Always cite where information came from when possible.
        """),
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔬 AI Research Agent              ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");

while (true)
{
    Console.Write("\n📌 Research topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    // Reset for each new research session
    notebook.Clear();
    messages.RemoveRange(1, messages.Count - 1);
    messages.Add(new(ChatRole.User,
        $"Research the following topic and produce a detailed summary:\n\n{topic}"));

    Console.WriteLine("\n⏳ Researching… (the agent will search the web and take notes)\n");

    var response = await client.GetResponseAsync(messages, chatOptions);
    messages.AddMessages(response);

    Console.WriteLine("═══════════════ Research Report ═══════════════");
    Console.WriteLine(response.Text);
    Console.WriteLine("═══════════════════════════════════════════════\n");
}

Console.WriteLine("Goodbye!");

// ──────────────────────────────────────────────
//  Web Search Tool
// ──────────────────────────────────────────────
static partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent",
              "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
        },
    };

    [Description("Searches the web for a query and returns a list of result snippets. "
        + "Use varied and specific queries to get the best results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍  Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseSearchResults(html);
            if (results.Count == 0)
                return "No results found for this query.";

            var sb = new StringBuilder();
            foreach (var (title, snippet) in results.Take(6))
                sb.AppendLine($"• {title}\n  {snippet}\n");

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet)> ParseSearchResults(string html)
    {
        var results = new List<(string, string)>();

        var titlePattern = TitleRegex();
        var snippetPattern = SnippetRegex();

        var titles = titlePattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        var count = Math.Min(titles.Count, snippets.Count);
        for (var i = 0; i < count; i++)
        {
            var title = StripHtml(titles[i].Groups[1].Value);
            var snippet = StripHtml(snippets[i].Groups[1].Value);
            if (!string.IsNullOrWhiteSpace(title))
                results.Add((title, snippet));
        }

        return results;
    }

    private static string StripHtml(string html) =>
        WebUtility.HtmlDecode(TagRegex().Replace(html, "")).Trim();

    [GeneratedRegex("""<a[^>]+class="result__a"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex TitleRegex();

    [GeneratedRegex("""<a[^>]+class="result__snippet"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex TagRegex();
}

