class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Records a research note. Use this to save important facts, "
        + "statistics, or quotes discovered during research.")]
    public string TakeNote(
        [Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝  Note #{_notes.Count} recorded");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Returns all notes taken so far during the research session.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0) return "No notes recorded yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

